let file = """{"version":3,"file":"Load3D-C9ZnHnF5.js","names":[],"sources":["../../src/components/load3d/menubar/usePopoverExclusivity.ts","../../src/components/load3d/menubar/AnimationMenuStrip.vue","../../src/components/load3d/menubar/AnimationMenuStrip.vue","../../src/components/load3d/menubar/CameraMenuGroup.vue","../../src/components/load3d/menubar/CameraMenuGroup.vue","../../src/components/load3d/menubar/GizmoMenuGroup.vue","../../src/components/load3d/menubar/GizmoMenuGroup.vue","../../src/components/load3d/menubar/HdriMenuGroup.vue","../../src/components/load3d/menubar/HdriMenuGroup.vue","../../src/components/load3d/menubar/LightMenuGroup.vue","../../src/components/load3d/menubar/LightMenuGroup.vue","../../src/components/load3d/menubar/ModelMenuGroup.vue","../../src/components/load3d/menubar/ModelMenuGroup.vue","../../src/components/load3d/menubar/RecordMenuControl.vue","../../src/components/load3d/menubar/RecordMenuControl.vue","../../src/components/load3d/menubar/SceneMenuGroup.vue","../../src/components/load3d/menubar/SceneMenuGroup.vue","../../src/components/load3d/controls/ViewerControls.vue","../../src/components/load3d/controls/ViewerControls.vue","../../src/components/load3d/Load3DMenuBar.vue","../../src/components/load3d/Load3DMenuBar.vue","../../src/components/load3d/Load3DScene.vue","../../src/components/load3d/Load3DScene.vue","../../src/components/load3d/Load3D.vue","../../src/components/load3d/Load3D.vue"],"sourcesContent":["import type { InjectionKey, Ref, WritableComputedRef } from 'vue'\nimport { computed, inject, provide, ref } from 'vue'\n\nconst openPopoverKey: InjectionKey<Ref<string | null>> =\n  Symbol('load3dOpenPopover')\n\n/**\n * Keeps Load3D menubar popovers mutually exclusive. `@pointerdown.stop` on the\n * Load3D container blocks reka-ui's document-level outside-pointerdown\n * dismissal, so sibling popovers cannot close each other on their own — on\n * Safari not even via the focus-outside fallback, because clicking a button\n * there does not focus it.\n *\n * Call once per component; the returned factory yields a writable `open`\n * binding per popover id. The open-popover id is shared with ancestor scopes\n * via provide/inject, so exclusivity spans the whole menubar.\n */\nexport function usePopoverExclusivity() {\n  const openPopover = inject(openPopoverKey, null) ?? ref<string | null>(null)\n  provide(openPopoverKey, openPopover)\n  return function exclusivePopover(id: string): WritableComputedRef<boolean> {\n    return computed({\n      get: () => openPopover.value === id,\n      set: (open) => {\n        if (open) openPopover.value = id\n        else if (openPopover.value === id) openPopover.value = null\n      }\n    })\n  }\n}\n","<template>\n  <div\n    class=\"flex h-10 shrink-0 items-center gap-1 bg-interface-menu-surface px-2\"\n    data-testid=\"load3d-animation-strip\"\n    @wheel.stop\n  >\n    <Button\n      variant=\"textonly\"\n      size=\"icon\"\n      :tooltip=\"playLabel\"\n      type=\"button\"\n      :aria-label=\"playLabel\"\n      @click=\"playing = !playing\"\n    >\n      <i\n        :class=\"\n          cn(playing ? 'icon-[lucide--pause]' : 'icon-[lucide--play]', 'size-4')\n        \"\n      />\n    </Button>\n\n    <Slider\n      :model-value=\"[animationProgress]\"\n      :min=\"0\"\n      :max=\"100\"\n      :step=\"0.1\"\n      class=\"min-w-12 flex-1\"\n      @update:model-value=\"handleSliderChange\"\n    />\n\n    <span\n      v-if=\"!compact\"\n      class=\"shrink-0 text-xs text-base-foreground tabular-nums\"\n      data-testid=\"load3d-animation-time\"\n    >\n      {{ formatAnimationTime(currentTime) }} /\n      {{ formatAnimationTime(animationDuration) }}\n    </span>\n\n    <Popover v-model:open=\"speedOpen\">\n      <PopoverTrigger as-child>\n        <Button\n          variant=\"textonly\"\n          size=\"unset\"\n          :tooltip=\"t('load3d.menuBar.playbackSpeed')\"\n          :class=\"chipClass\"\n          type=\"button\"\n          :aria-label=\"t('load3d.menuBar.playbackSpeed')\"\n        >\n          {{ speedLabel }}\n          <i class=\"icon-[lucide--chevron-down] size-4 opacity-70\" />\n        </Button>\n      </PopoverTrigger>\n      <PopoverContent\n        side=\"top\"\n        align=\"end\"\n        :side-offset=\"8\"\n        :class=\"menuPanelClass\"\n      >\n        <button\n          v-for=\"speed in speedOptions\"\n          :key=\"speed\"\n          type=\"button\"\n          :class=\"\n            cn(\n              menuButtonClass,\n              selectedSpeed === speed && selectedMenuButtonClass\n            )\n          \"\n          :aria-pressed=\"selectedSpeed === speed\"\n          @click=\"setSpeed(speed)\"\n        >\n          {{ formatSpeed(speed) }}\n        </button>\n      </PopoverContent>\n    </Popover>\n\n    <Popover v-model:open=\"clipOpen\">\n      <PopoverTrigger as-child>\n        <Button\n          variant=\"textonly\"\n          size=\"unset\"\n          :tooltip=\"t('load3d.menuBar.animationClip')\"\n          :class=\"cn(chipClass, 'max-w-40')\"\n          type=\"button\"\n          :aria-label=\"t('load3d.menuBar.animationClip')\"\n        >\n          <i class=\"icon-[lucide--clapperboard] size-4 shrink-0\" />\n          <span v-if=\"!compact\" class=\"truncate\">{{ selectedClipName }}</span>\n          <i class=\"icon-[lucide--chevron-down] size-4 shrink-0 opacity-70\" />\n        </Button>\n      </PopoverTrigger>\n      <PopoverContent\n        side=\"top\"\n        align=\"end\"\n        :side-offset=\"8\"\n        :class=\"menuPanelClass\"\n      >\n        <button\n          v-for=\"clip in animations\"\n          :key=\"clip.index\"\n          type=\"button\"\n          :class=\"\n            cn(\n              menuButtonClass,\n              selectedAnimation === clip.index && selectedMenuButtonClass\n            )\n          \"\n          :aria-pressed=\"selectedAnimation === clip.index\"\n          @click=\"setClip(clip.index)\"\n        >\n          <span class=\"truncate\">{{ clip.name }}</span>\n        </button>\n      </PopoverContent>\n    </Popover>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { PopoverTrigger } from 'reka-ui'\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport { formatAnimationTime } from '@/components/load3d/formatAnimationTime'\nimport {\n  chipClass,\n  menuPanelClass\n} from '@/components/load3d/menubar/menuBarStyles'\nimport { usePopoverExclusivity } from '@/components/load3d/menubar/usePopoverExclusivity'\nimport Button from '@/components/ui/button/Button.vue'\nimport Popover from '@/components/ui/popover/Popover.vue'\nimport PopoverContent from '@/components/ui/popover/PopoverContent.vue'\nimport {\n  menuButtonClass,\n  selectedMenuButtonClass\n} from '@/components/ui/menu/menuStyles'\nimport Slider from '@/components/ui/slider/Slider.vue'\nimport type { AnimationItem } from '@/extensions/core/load3d/interfaces'\n\nconst {\n  animations = [],\n  animationDuration = 0,\n  compact = false\n} = defineProps<{\n  animations?: AnimationItem[]\n  animationDuration?: number\n  compact?: boolean\n}>()\n\nconst playing = defineModel<boolean>('playing', { default: false })\nconst selectedSpeed = defineModel<number>('selectedSpeed', { default: 1 })\nconst selectedAnimation = defineModel<number>('selectedAnimation', {\n  default: 0\n})\nconst animationProgress = defineModel<number>('animationProgress', {\n  default: 0\n})\n\nconst emit = defineEmits<{\n  seek: [progress: number]\n}>()\n\nconst { t } = useI18n()\n\nconst speedOptions = [0.1, 0.5, 1, 1.5, 2]\n\nconst exclusivePopover = usePopoverExclusivity()\nconst speedOpen = exclusivePopover('animation-speed')\nconst clipOpen = exclusivePopover('animation-clip')\n\nconst playLabel = computed(() => t(playing.value ? 'g.pause' : 'g.play'))\nconst speedLabel = computed(() => formatSpeed(selectedSpeed.value))\nconst selectedClipName = computed(\n  () =>\n    animations.find((clip) => clip.index === selectedAnimation.value)?.name ??\n    ''\n)\nconst currentTime = computed(\n  () => (animationProgress.value / 100) * animationDuration\n)\n\nfunction formatSpeed(speed: number) {\n  return `${speed}x`\n}\n\nfunction setSpeed(speed: number) {\n  selectedSpeed.value = speed\n  speedOpen.value = false\n}\n\nfunction setClip(index: number) {\n  selectedAnimation.value = index\n  clipOpen.value = false\n}\n\nfunction handleSliderChange(value: number[] | undefined) {\n  if (!value) return\n  const progress = value[0]\n  animationProgress.value = progress\n  emit('seek', progress)\n}\n</script>\n","<template>\n  <div\n    class=\"flex h-10 shrink-0 items-center gap-1 bg-interface-menu-surface px-2\"\n    data-testid=\"load3d-animation-strip\"\n    @wheel.stop\n  >\n    <Button\n      variant=\"textonly\"\n      size=\"icon\"\n      :tooltip=\"playLabel\"\n      type=\"button\"\n      :aria-label=\"playLabel\"\n      @click=\"playing = !playing\"\n    >\n      <i\n        :class=\"\n          cn(playing ? 'icon-[lucide--pause]' : 'icon-[lucide--play]', 'size-4')\n        \"\n      />\n    </Button>\n\n    <Slider\n      :model-value=\"[animationProgress]\"\n      :min=\"0\"\n      :max=\"100\"\n      :step=\"0.1\"\n      class=\"min-w-12 flex-1\"\n      @update:model-value=\"handleSliderChange\"\n    />\n\n    <span\n      v-if=\"!compact\"\n      class=\"shrink-0 text-xs text-base-foreground tabular-nums\"\n      data-testid=\"load3d-animation-time\"\n    >\n      {{ formatAnimationTime(currentTime) }} /\n      {{ formatAnimationTime(animationDuration) }}\n    </span>\n\n    <Popover v-model:open=\"speedOpen\">\n      <PopoverTrigger as-child>\n        <Button\n          variant=\"textonly\"\n          size=\"unset\"\n          :tooltip=\"t('load3d.menuBar.playbackSpeed')\"\n          :class=\"chipClass\"\n          type=\"button\"\n          :aria-label=\"t('load3d.menuBar.playbackSpeed')\"\n        >\n          {{ speedLabel }}\n          <i class=\"icon-[lucide--chevron-down] size-4 opacity-70\" />\n        </Button>\n      </PopoverTrigger>\n      <PopoverContent\n        side=\"top\"\n        align=\"end\"\n        :side-offset=\"8\"\n        :class=\"menuPanelClass\"\n      >\n        <button\n          v-for=\"speed in speedOptions\"\n          :key=\"speed\"\n          type=\"button\"\n          :class=\"\n            cn(\n              menuButtonClass,\n              selectedSpeed === speed && selectedMenuButtonClass\n            )\n          \"\n          :aria-pressed=\"selectedSpeed === speed\"\n          @click=\"setSpeed(speed)\"\n        >\n          {{ formatSpeed(speed) }}\n        </button>\n      </PopoverContent>\n    </Popover>\n\n    <Popover v-model:open=\"clipOpen\">\n      <PopoverTrigger as-child>\n        <Button\n          variant=\"textonly\"\n          size=\"unset\"\n          :tooltip=\"t('load3d.menuBar.animationClip')\"\n          :class=\"cn(chipClass, 'max-w-40')\"\n          type=\"button\"\n          :aria-label=\"t('load3d.menuBar.animationClip')\"\n        >\n          <i class=\"icon-[lucide--clapperboard] size-4 shrink-0\" />\n          <span v-if=\"!compact\" class=\"truncate\">{{ selectedClipName }}</span>\n          <i class=\"icon-[lucide--chevron-down] size-4 shrink-0 opacity-70\" />\n        </Button>\n      </PopoverTrigger>\n      <PopoverContent\n        side=\"top\"\n        align=\"end\"\n        :side-offset=\"8\"\n        :class=\"menuPanelClass\"\n      >\n        <button\n          v-for=\"clip in animations\"\n          :key=\"clip.index\"\n          type=\"button\"\n          :class=\"\n            cn(\n              menuButtonClass,\n              selectedAnimation === clip.index && selectedMenuButtonClass\n            )\n          \"\n          :aria-pressed=\"selectedAnimation === clip.index\"\n          @click=\"setClip(clip.index)\"\n        >\n          <span class=\"truncate\">{{ clip.name }}</span>\n        </button>\n      </PopoverContent>\n    </Popover>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { PopoverTrigger } from 'reka-ui'\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport { formatAnimationTime } from '@/components/load3d/formatAnimationTime'\nimport {\n  chipClass,\n  menuPanelClass\n} from '@/components/load3d/menubar/menuBarStyles'\nimport { usePopoverExclusivity } from '@/components/load3d/menubar/usePopoverExclusivity'\nimport Button from '@/components/ui/button/Button.vue'\nimport Popover from '@/components/ui/popover/Popover.vue'\nimport PopoverContent from '@/components/ui/popover/PopoverContent.vue'\nimport {\n  menuButtonClass,\n  selectedMenuButtonClass\n} from '@/components/ui/menu/menuStyles'\nimport Slider from '@/components/ui/slider/Slider.vue'\nimport type { AnimationItem } from '@/extensions/core/load3d/interfaces'\n\nconst {\n  animations = [],\n  animationDuration = 0,\n  compact = false\n} = defineProps<{\n  animations?: AnimationItem[]\n  animationDuration?: number\n  compact?: boolean\n}>()\n\nconst playing = defineModel<boolean>('playing', { default: false })\nconst selectedSpeed = defineModel<number>('selectedSpeed', { default: 1 })\nconst selectedAnimation = defineModel<number>('selectedAnimation', {\n  default: 0\n})\nconst animationProgress = defineModel<number>('animationProgress', {\n  default: 0\n})\n\nconst emit = defineEmits<{\n  seek: [progress: number]\n}>()\n\nconst { t } = useI18n()\n\nconst speedOptions = [0.1, 0.5, 1, 1.5, 2]\n\nconst exclusivePopover = usePopoverExclusivity()\nconst speedOpen = exclusivePopover('animation-speed')\nconst clipOpen = exclusivePopover('animation-clip')\n\nconst playLabel = computed(() => t(playing.value ? 'g.pause' : 'g.play'))\nconst speedLabel = computed(() => formatSpeed(selectedSpeed.value))\nconst selectedClipName = computed(\n  () =>\n    animations.find((clip) => clip.index === selectedAnimation.value)?.name ??\n    ''\n)\nconst currentTime = computed(\n  () => (animationProgress.value / 100) * animationDuration\n)\n\nfunction formatSpeed(speed: number) {\n  return `${speed}x`\n}\n\nfunction setSpeed(speed: number) {\n  selectedSpeed.value = speed\n  speedOpen.value = false\n}\n\nfunction setClip(index: number) {\n  selectedAnimation.value = index\n  clipOpen.value = false\n}\n\nfunction handleSliderChange(value: number[] | undefined) {\n  if (!value) return\n  const progress = value[0]\n  animationProgress.value = progress\n  emit('seek', progress)\n}\n</script>\n","<template>\n  <Button\n    variant=\"textonly\"\n    size=\"unset\"\n    :tooltip=\"t('load3d.menuBar.switchProjection')\"\n    tooltip-side=\"bottom\"\n    :class=\"actionClass(false)\"\n    type=\"button\"\n    :aria-label=\"compact ? t('load3d.menuBar.switchProjection') : undefined\"\n    @click=\"switchCamera\"\n  >\n    <i class=\"icon-[lucide--camera] size-4\" />\n    <span v-if=\"!compact\">{{ cameraTypeLabel }}</span>\n  </Button>\n\n  <Button\n    v-if=\"hasCustomUp\"\n    variant=\"textonly\"\n    size=\"unset\"\n    :tooltip=\"upActionLabel\"\n    tooltip-side=\"bottom\"\n    :class=\"actionClass(false)\"\n    type=\"button\"\n    :aria-label=\"compact ? upActionLabel : undefined\"\n    @click=\"toggleUp\"\n  >\n    <i\n      :class=\"\n        cn(\n          useCustomUp ? 'icon-[lucide--compass]' : 'icon-[lucide--rotate-ccw]',\n          'size-4'\n        )\n      \"\n    />\n    <span v-if=\"!compact\">{{ upLabel }}</span>\n  </Button>\n\n  <Popover v-if=\"isPerspective\" v-model:open=\"fovOpen\">\n    <PopoverTrigger as-child>\n      <Button\n        variant=\"textonly\"\n        size=\"unset\"\n        :tooltip=\"t('load3d.menuBar.fov')\"\n        tooltip-side=\"bottom\"\n        :class=\"actionClass(false)\"\n        type=\"button\"\n        :aria-label=\"compact ? t('load3d.menuBar.fov') : undefined\"\n      >\n        <i class=\"icon-[lucide--focus] size-4\" />\n        <span v-if=\"!compact\">{{ t('load3d.menuBar.fov') }}</span>\n      </Button>\n    </PopoverTrigger>\n    <PopoverContent\n      side=\"bottom\"\n      align=\"start\"\n      :side-offset=\"8\"\n      :class=\"cn(formPanelClass, 'w-56')\"\n    >\n      <div class=\"flex flex-col gap-2 p-1\">\n        <span class=\"text-sm text-base-foreground\">{{ t('load3d.fov') }}</span>\n        <Slider\n          :model-value=\"[fov]\"\n          :min=\"10\"\n          :max=\"150\"\n          :step=\"1\"\n          class=\"w-full\"\n          @update:model-value=\"setFov\"\n        />\n      </div>\n    </PopoverContent>\n  </Popover>\n</template>\n\n<script setup lang=\"ts\">\nimport { PopoverTrigger } from 'reka-ui'\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport {\n  actionClass,\n  formPanelClass\n} from '@/components/load3d/menubar/menuBarStyles'\nimport { usePopoverExclusivity } from '@/components/load3d/menubar/usePopoverExclusivity'\nimport Button from '@/components/ui/button/Button.vue'\nimport Popover from '@/components/ui/popover/Popover.vue'\nimport PopoverContent from '@/components/ui/popover/PopoverContent.vue'\nimport Slider from '@/components/ui/slider/Slider.vue'\nimport type { CameraConfig } from '@/extensions/core/load3d/interfaces'\n\nconst { compact = false } = defineProps<{\n  compact?: boolean\n}>()\n\nconst config = defineModel<CameraConfig>('config')\n\nconst { t } = useI18n()\n\nconst fovOpen = usePopoverExclusivity()('camera-fov')\n\nconst cameraType = computed(() => config.value?.cameraType)\nconst isPerspective = computed(() => cameraType.value === 'perspective')\nconst cameraTypeLabel = computed(() =>\n  cameraType.value ? t(`load3d.cameraType.${cameraType.value}`) : ''\n)\nconst fov = computed(() => config.value?.fov ?? 0)\nconst hasCustomUp = computed(() => config.value?.hasCustomUp === true)\nconst useCustomUp = computed(\n  () => config.value?.hasCustomUp === true && config.value.useCustomUp\n)\nconst upActionLabel = computed(() =>\n  useCustomUp.value ? t('load3d.useNaturalUp') : t('load3d.useCustomUp')\n)\nconst upLabel = computed(() =>\n  useCustomUp.value\n    ? t('load3d.menuBar.customUp')\n    : t('load3d.menuBar.naturalUp')\n)\n\nfunction toggleUp() {\n  const current = config.value\n  if (!current?.hasCustomUp) return\n  current.useCustomUp = !current.useCustomUp\n}\n\nfunction switchCamera() {\n  if (!config.value) return\n  config.value.cameraType =\n    config.value.cameraType === 'perspective' ? 'orthographic' : 'perspective'\n}\n\nfunction setFov(value?: number[]) {\n  if (config.value && value?.length) config.value.fov = value[0]\n}\n</script>\n","<template>\n  <Button\n    variant=\"textonly\"\n    size=\"unset\"\n    :tooltip=\"t('load3d.menuBar.switchProjection')\"\n    tooltip-side=\"bottom\"\n    :class=\"actionClass(false)\"\n    type=\"button\"\n    :aria-label=\"compact ? t('load3d.menuBar.switchProjection') : undefined\"\n    @click=\"switchCamera\"\n  >\n    <i class=\"icon-[lucide--camera] size-4\" />\n    <span v-if=\"!compact\">{{ cameraTypeLabel }}</span>\n  </Button>\n\n  <Button\n    v-if=\"hasCustomUp\"\n    variant=\"textonly\"\n    size=\"unset\"\n    :tooltip=\"upActionLabel\"\n    tooltip-side=\"bottom\"\n    :class=\"actionClass(false)\"\n    type=\"button\"\n    :aria-label=\"compact ? upActionLabel : undefined\"\n    @click=\"toggleUp\"\n  >\n    <i\n      :class=\"\n        cn(\n          useCustomUp ? 'icon-[lucide--compass]' : 'icon-[lucide--rotate-ccw]',\n          'size-4'\n        )\n      \"\n    />\n    <span v-if=\"!compact\">{{ upLabel }}</span>\n  </Button>\n\n  <Popover v-if=\"isPerspective\" v-model:open=\"fovOpen\">\n    <PopoverTrigger as-child>\n      <Button\n        variant=\"textonly\"\n        size=\"unset\"\n        :tooltip=\"t('load3d.menuBar.fov')\"\n        tooltip-side=\"bottom\"\n        :class=\"actionClass(false)\"\n        type=\"button\"\n        :aria-label=\"compact ? t('load3d.menuBar.fov') : undefined\"\n      >\n        <i class=\"icon-[lucide--focus] size-4\" />\n        <span v-if=\"!compact\">{{ t('load3d.menuBar.fov') }}</span>\n      </Button>\n    </PopoverTrigger>\n    <PopoverContent\n      side=\"bottom\"\n      align=\"start\"\n      :side-offset=\"8\"\n      :class=\"cn(formPanelClass, 'w-56')\"\n    >\n      <div class=\"flex flex-col gap-2 p-1\">\n        <span class=\"text-sm text-base-foreground\">{{ t('load3d.fov') }}</span>\n        <Slider\n          :model-value=\"[fov]\"\n          :min=\"10\"\n          :max=\"150\"\n          :step=\"1\"\n          class=\"w-full\"\n          @update:model-value=\"setFov\"\n        />\n      </div>\n    </PopoverContent>\n  </Popover>\n</template>\n\n<script setup lang=\"ts\">\nimport { PopoverTrigger } from 'reka-ui'\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport {\n  actionClass,\n  formPanelClass\n} from '@/components/load3d/menubar/menuBarStyles'\nimport { usePopoverExclusivity } from '@/components/load3d/menubar/usePopoverExclusivity'\nimport Button from '@/components/ui/button/Button.vue'\nimport Popover from '@/components/ui/popover/Popover.vue'\nimport PopoverContent from '@/components/ui/popover/PopoverContent.vue'\nimport Slider from '@/components/ui/slider/Slider.vue'\nimport type { CameraConfig } from '@/extensions/core/load3d/interfaces'\n\nconst { compact = false } = defineProps<{\n  compact?: boolean\n}>()\n\nconst config = defineModel<CameraConfig>('config')\n\nconst { t } = useI18n()\n\nconst fovOpen = usePopoverExclusivity()('camera-fov')\n\nconst cameraType = computed(() => config.value?.cameraType)\nconst isPerspective = computed(() => cameraType.value === 'perspective')\nconst cameraTypeLabel = computed(() =>\n  cameraType.value ? t(`load3d.cameraType.${cameraType.value}`) : ''\n)\nconst fov = computed(() => config.value?.fov ?? 0)\nconst hasCustomUp = computed(() => config.value?.hasCustomUp === true)\nconst useCustomUp = computed(\n  () => config.value?.hasCustomUp === true && config.value.useCustomUp\n)\nconst upActionLabel = computed(() =>\n  useCustomUp.value ? t('load3d.useNaturalUp') : t('load3d.useCustomUp')\n)\nconst upLabel = computed(() =>\n  useCustomUp.value\n    ? t('load3d.menuBar.customUp')\n    : t('load3d.menuBar.naturalUp')\n)\n\nfunction toggleUp() {\n  const current = config.value\n  if (!current?.hasCustomUp) return\n  current.useCustomUp = !current.useCustomUp\n}\n\nfunction switchCamera() {\n  if (!config.value) return\n  config.value.cameraType =\n    config.value.cameraType === 'perspective' ? 'orthographic' : 'perspective'\n}\n\nfunction setFov(value?: number[]) {\n  if (config.value && value?.length) config.value.fov = value[0]\n}\n</script>\n","<template>\n  <Button\n    variant=\"textonly\"\n    size=\"unset\"\n    :tooltip=\"t('load3d.gizmo.toggle')\"\n    tooltip-side=\"bottom\"\n    :class=\"actionClass(gizmoEnabled)\"\n    :aria-pressed=\"gizmoEnabled\"\n    type=\"button\"\n    :aria-label=\"compact ? t('load3d.gizmo.toggle') : undefined\"\n    @click=\"toggleGizmo\"\n  >\n    <i class=\"icon-[lucide--axis-3d] size-4\" />\n    <span v-if=\"!compact\">{{ t('load3d.gizmo.toggle') }}</span>\n  </Button>\n\n  <template v-if=\"gizmoEnabled\">\n    <template v-if=\"!compact\">\n      <Button\n        v-for=\"m in modeDefs\"\n        :key=\"m.mode\"\n        variant=\"textonly\"\n        size=\"unset\"\n        :tooltip=\"t(m.labelKey)\"\n        tooltip-side=\"bottom\"\n        :class=\"actionClass(gizmoMode === m.mode)\"\n        :aria-pressed=\"gizmoMode === m.mode\"\n        type=\"button\"\n        @click=\"setGizmoMode(m.mode)\"\n      >\n        <i :class=\"cn(m.icon, 'size-4')\" />\n        <span>{{ t(m.labelKey) }}</span>\n      </Button>\n      <Button\n        variant=\"textonly\"\n        size=\"unset\"\n        :tooltip=\"t('load3d.gizmo.reset')\"\n        tooltip-side=\"bottom\"\n      