v')\n\nfunction toggleGrid() {\n  if (config.value) config.value.showGrid = !config.value.showGrid\n}\n\nfunction setBackgroundColor(event: Event) {\n  if (config.value) {\n    config.value.backgroundColor = (event.target as HTMLInputElement).value\n  }\n}\n\nfunction onBackgroundImagePicked(event: Event) {\n  const input = event.target as HTMLInputElement\n  const file = input.files?.[0]\n  input.value = ''\n  if (file) emit('updateBackgroundImage', file)\n}\n\nfunction removeBackgroundImage() {\n  emit('updateBackgroundImage', null)\n}\n\nfunction togglePanorama() {\n  if (!config.value) return\n  config.value.backgroundRenderMode =\n    config.value.backgroundRenderMode === 'panorama' ? 'tiled' : 'panorama'\n}\n\nfunction setFov(value?: number[]) {\n  if (value?.length) fov.value = value[0]\n}\n</script>\n","<template>\n  <div class=\"relative rounded-lg bg-backdrop/30\">\n    <div class=\"flex flex-col gap-2\">\n      <Button\n        :tooltip=\"t('load3d.openIn3DViewer')\"\n        tooltip-side=\"right\"\n        size=\"icon\"\n        variant=\"textonly\"\n        class=\"rounded-full\"\n        :aria-label=\"t('load3d.openIn3DViewer')\"\n        @click=\"openIn3DViewer\"\n      >\n        <i class=\"pi pi-expand text-lg text-base-foreground\" />\n      </Button>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useI18n } from 'vue-i18n'\n\nimport Load3DViewerContent from '@/components/load3d/Load3dViewerContent.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { LOAD3D_VIEWER_DIALOG_PROPS } from '@/components/load3d/load3dViewerDialog'\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport { useLoad3dService } from '@/services/load3dService'\nimport { useDialogStore } from '@/stores/dialogStore'\n\nconst { t } = useI18n()\nconst { node } = defineProps<{\n  node: LGraphNode\n}>()\n\nconst openIn3DViewer = () => {\n  const props = { node: node }\n\n  useDialogStore().showDialog({\n    key: 'global-load3d-viewer',\n    title: t('load3d.viewer.title'),\n    component: Load3DViewerContent,\n    props: props,\n    dialogComponentProps: {\n      ...LOAD3D_VIEWER_DIALOG_PROPS,\n      onClose: async () => {\n        await useLoad3dService().handleViewerClose(props.node)\n      }\n    }\n  })\n}\n</script>\n\n<style scoped></style>\n","<template>\n  <div class=\"relative rounded-lg bg-backdrop/30\">\n    <div class=\"flex flex-col gap-2\">\n      <Button\n        :tooltip=\"t('load3d.openIn3DViewer')\"\n        tooltip-side=\"right\"\n        size=\"icon\"\n        variant=\"textonly\"\n        class=\"rounded-full\"\n        :aria-label=\"t('load3d.openIn3DViewer')\"\n        @click=\"openIn3DViewer\"\n      >\n        <i class=\"pi pi-expand text-lg text-base-foreground\" />\n      </Button>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useI18n } from 'vue-i18n'\n\nimport Load3DViewerContent from '@/components/load3d/Load3dViewerContent.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { LOAD3D_VIEWER_DIALOG_PROPS } from '@/components/load3d/load3dViewerDialog'\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport { useLoad3dService } from '@/services/load3dService'\nimport { useDialogStore } from '@/stores/dialogStore'\n\nconst { t } = useI18n()\nconst { node } = defineProps<{\n  node: LGraphNode\n}>()\n\nconst openIn3DViewer = () => {\n  const props = { node: node }\n\n  useDialogStore().showDialog({\n    key: 'global-load3d-viewer',\n    title: t('load3d.viewer.title'),\n    component: Load3DViewerContent,\n    props: props,\n    dialogComponentProps: {\n      ...LOAD3D_VIEWER_DIALOG_PROPS,\n      onClose: async () => {\n        await useLoad3dService().handleViewerClose(props.node)\n      }\n    }\n  })\n}\n</script>\n\n<style scoped></style>\n","<template>\n  <div class=\"flex size-full flex-col\">\n    <div\n      ref=\"topBarRef\"\n      class=\"flex h-10 shrink-0 items-center gap-1 bg-interface-menu-surface px-2\"\n      @wheel.stop\n    >\n      <Popover v-model:open=\"categoryMenuOpen\">\n        <PopoverTrigger as-child>\n          <Button\n            variant=\"textonly\"\n            size=\"unset\"\n            :tooltip=\"compact ? activeLabel : ''\"\n            tooltip-side=\"bottom\"\n            :class=\"chipClass\"\n            type=\"button\"\n            :aria-label=\"compact ? activeLabel : undefined\"\n            data-testid=\"load3d-category-menu\"\n          >\n            <i v-if=\"compact\" :class=\"cn(activeIcon, 'size-4')\" />\n            <template v-else>{{ activeLabel }}</template>\n            <i class=\"icon-[lucide--chevron-down] size-4 opacity-70\" />\n          </Button>\n        </PopoverTrigger>\n        <PopoverContent\n          side=\"bottom\"\n          align=\"start\"\n          :side-offset=\"8\"\n          :class=\"menuPanelClass\"\n        >\n          <button\n            v-for=\"c in categoryDefs\"\n            :key=\"c.key\"\n            type=\"button\"\n            :class=\"\n              cn(\n                menuButtonClass,\n                activeCategory === c.key && selectedMenuButtonClass\n              )\n            \"\n            :aria-pressed=\"activeCategory === c.key\"\n            @click=\"selectCategory(c.key)\"\n          >\n            <i :class=\"cn(c.icon, 'size-4')\" />\n            {{ c.label }}\n          </button>\n        </PopoverContent>\n      </Popover>\n\n      <div class=\"mx-1 h-5 w-px shrink-0 bg-interface-menu-stroke\" />\n\n      <SceneMenuGroup\n        v-if=\"activeCategory === 'scene' && sceneConfig\"\n        v-model:config=\"sceneConfig\"\n        v-model:fov=\"cameraFov\"\n        :compact\n        :can-use-background-image=\"canUseBackgroundImage\"\n        :hdri-active=\"hdriActive\"\n        @update-background-image=\"emit('updateBackgroundImage', $event)\"\n      />\n      <ModelMenuGroup\n        v-else-if=\"activeCategory === 'model' && modelConfig\"\n        v-model:config=\"modelConfig\"\n        :compact\n        :material-modes=\"materialModes\"\n        :has-skeleton=\"hasSkeleton\"\n      />\n      <CameraMenuGroup\n        v-else-if=\"activeCategory === 'camera' && cameraConfig\"\n        v-model:config=\"cameraConfig\"\n        :compact\n      />\n      <LightMenuGroup\n        v-else-if=\"activeCategory === 'light' && lightConfig && modelConfig\"\n        v-model:config=\"lightConfig\"\n        :compact\n        :is-original-material=\"isOriginalMaterial\"\n      />\n      <HdriMenuGroup\n        v-else-if=\"activeCategory === 'hdri' && lightConfig\"\n        v-model:config=\"lightConfig\"\n        :compact\n        :scene-has-image=\"sceneHasImage\"\n        @update-hdri-file=\"emit('updateHdriFile', $event)\"\n      />\n      <GizmoMenuGroup\n        v-else-if=\"activeCategory === 'gizmo' && modelConfig\"\n        v-model:config=\"modelConfig\"\n        :compact\n        @toggle-gizmo=\"emit('toggleGizmo', $event)\"\n        @set-gizmo-mode=\"emit('setGizmoMode', $event)\"\n        @reset-gizmo-transform=\"emit('resetGizmoTransform')\"\n      />\n    </div>\n\n    <div class=\"relative min-h-0 flex-1 overflow-hidden\">\n      <slot />\n      <div\n        v-if=\"isRecording\"\n        class=\"pointer-events-none absolute inset-0 border-2 border-node-component-executing\"\n      />\n    </div>\n\n    <AnimationMenuStrip\n      v-if=\"animations.length > 0\"\n      v-model:playing=\"playing\"\n      v-model:selected-speed=\"selectedSpeed\"\n      v-model:selected-animation=\"selectedAnimation\"\n      v-model:animation-progress=\"animationProgress\"\n      :animations=\"animations\"\n      :animation-duration=\"animationDuration\"\n      :compact\n      @seek=\"emit('seek', $event)\"\n    />\n\n    <div\n      class=\"flex h-10 shrink-0 items-center justify-between gap-1 bg-interface-menu-surface px-2\"\n      @wheel.stop\n    >\n      <div class=\"flex items-center gap-1\">\n        <RecordMenuControl\n          v-if=\"canUseRecording\"\n          v-model:is-recording=\"isRecording\"\n          v-model:has-recording=\"hasRecording\"\n          v-model:recording-duration=\"recordingDuration\"\n          :compact\n          @start-recording=\"emit('startRecording')\"\n          @stop-recording=\"emit('stopRecording')\"\n          @export-recording=\"emit('exportRecording')\"\n          @clear-recording=\"emit('clearRecording')\"\n        />\n      </div>\n      <div class=\"flex items-center gap-1\">\n        <ViewerControls\n          v-if=\"enableViewer && node\"\n          :node=\"node as LGraphNode\"\n        />\n        <Button\n          v-if=\"canFitToViewer\"\n          variant=\"textonly\"\n          size=\"icon\"\n          :tooltip=\"t('load3d.fitToViewer')\"\n          type=\"button\"\n          :aria-label=\"t('load3d.fitToViewer')\"\n          @click=\"emit('fitToViewer')\"\n        >\n          <i class=\"icon-[lucide--scan] size-4\" />\n        </Button>\n        <Button\n          v-if=\"canCenterCameraOnModel\"\n          variant=\"textonly\"\n          size=\"icon\"\n          :tooltip=\"t('load3d.centerCameraOnModel')\"\n          type=\"button\"\n          :aria-label=\"t('load3d.centerCameraOnModel')\"\n          @click=\"emit('centerCamera')\"\n        >\n          <i class=\"icon-[lucide--crosshair] size-4\" />\n        </Button>\n        <Popover v-if=\"canExport\" v-model:open=\"exportOpen\">\n          <PopoverTrigger as-child>\n            <Button\n              variant=\"textonly\"\n              size=\"icon\"\n              :tooltip=\"t('load3d.export')\"\n              type=\"button\"\n              :aria-label=\"t('load3d.export')\"\n            >\n              <i class=\"icon-[lucide--download] size-4\" />\n            </Button>\n          </PopoverTrigger>\n          <PopoverContent\n            side=\"top\"\n            align=\"end\"\n            :side-offset=\"8\"\n            :class=\"menuPanelClass\"\n          >\n            <button\n              v-for=\"format in exportFormats\"\n              :key=\"format.value\"\n              type=\"button\"\n              :class=\"menuButtonClass\"\n              @click=\"onExport(format.value)\"\n            >\n              {{ format.label }}\n            </button>\n          </PopoverContent>\n        </Popover>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useElementSize } from '@vueuse/core'\nimport { PopoverTrigger } from 'reka-ui'\nimport { computed, ref, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport AnimationMenuStrip from '@/components/load3d/menubar/AnimationMenuStrip.vue'\nimport CameraMenuGroup from '@/components/load3d/menubar/CameraMenuGroup.vue'\nimport GizmoMenuGroup from '@/components/load3d/menubar/GizmoMenuGroup.vue'\nimport HdriMenuGroup from '@/components/load3d/menubar/HdriMenuGroup.vue'\nimport LightMenuGroup from '@/components/load3d/menubar/LightMenuGroup.vue'\nimport {\n  chipClass,\n  menuPanelClass\n} from '@/components/load3d/menubar/menuBarStyles'\nimport ModelMenuGroup from '@/components/load3d/menubar/ModelMenuGroup.vue'\nimport RecordMenuControl from '@/components/load3d/menubar/RecordMenuControl.vue'\nimport SceneMenuGroup from '@/components/load3d/menubar/SceneMenuGroup.vue'\nimport { usePopoverExclusivity } from '@/components/load3d/menubar/usePopoverExclusivity'\nimport ViewerControls from '@/components/load3d/controls/ViewerControls.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport Popover from '@/components/ui/popover/Popover.vue'\nimport PopoverContent from '@/components/ui/popover/PopoverContent.vue'\nimport {\n  menuButtonClass,\n  selectedMenuButtonClass\n} from '@/components/ui/menu/menuStyles'\nimport { getExportFormatOptions } from '@/extensions/core/load3d/constants'\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport type {\n  AnimationItem,\n  CameraConfig,\n  GizmoMode,\n  LightConfig,\n  MaterialMode,\n  ModelConfig,\n  SceneConfig\n} from '@/extensions/core/load3d/interfaces'\n\nconst {\n  animations = [],\n  animationDuration = 0,\n  canUseLighting = true,\n  canUseHdri = true,\n  canUseGizmo = true,\n  canExport = true,\n  canUseBackgroundImage = true,\n  canFitToViewer = true,\n  canCenterCameraOnModel = true,\n  canUseRecording = true,\n  enableViewer = false,\n  node = null,\n  materialModes = ['original', 'clay', 'normal', 'wireframe'],\n  hasSkeleton = false,\n  sourceFormat = null\n} = defineProps<{\n  animations?: AnimationItem[]\n  animationDuration?: number\n  canUseLighting?: boolean\n  canUseHdri?: boolean\n  canUseGizmo?: boolean\n  canExport?: boolean\n  canUseBackgroundImage?: boolean\n  canFitToViewer?: boolean\n  canCenterCameraOnModel?: boolean\n  canUseRecording?: boolean\n  enableViewer?: boolean\n  node?: LGraphNode | null\n  materialModes?: readonly MaterialMode[]\n  hasSkeleton?: boolean\n  sourceFormat?: string | null\n}>()\n\nconst sceneConfig = defineModel<SceneConfig>('sceneConfig')\nconst modelConfig = defineModel<ModelConfig>('modelConfig')\nconst cameraConfig = defineModel<CameraConfig>('cameraConfig')\nconst lightConfig = defineModel<LightConfig>('lightConfig')\nconst isRecording = defineModel<boolean>('isRecording')\nconst hasRecording = defineModel<boolean>('hasRecording')\nconst recordingDuration = defineModel<number>('recordingDuration')\nconst playing = defineModel<boolean>('playing')\nconst selectedSpeed = defineModel<number>('selectedSpeed')\nconst selectedAnimation = defineModel<number>('selectedAnimation')\nconst animationProgress = defineModel<number>('animationProgress')\n\nconst emit = defineEmits<{\n  (e: 'seek', progress: number): void\n  (e: 'updateBackgroundImage', file: File | null): void\n  (e: 'updateHdriFile', file: File | null): void\n  (e: 'exportModel', format: string): void\n  (e: 'fitToViewer'): void\n  (e: 'centerCamera'): void\n  (e: 'toggleGizmo', enabled: boolean): void\n  (e: 'setGizmoMode', mode: GizmoMode): void\n  (e: 'resetGizmoTransform'): void\n  (e: 'startRecording'): void\n  (e: 'stopRecording'): void\n  (e: 'exportRecording'): void\n  (e: 'clearRecording'): void\n}>()\n\nconst { t } = useI18n()\n\nconst categoryDefs = computed(() =>\n  [\n    {\n      key: 'scene',\n      label: t('load3d.scene'),\n      icon: 'icon-[lucide--layers]',\n      show: !!sceneConfig.value\n    },\n    {\n      key: 'model',\n      label: t('load3d.model3d'),\n      icon: 'icon-[lucide--box]',\n      show: !!modelConfig.value\n    },\n    {\n      key: 'camera',\n      label: t('load3d.camera'),\n      icon: 'icon-[lucide--camera]',\n      show: !!cameraConfig.value\n    },\n    {\n      key: 'light',\n      label: t('load3d.light'),\n      icon: 'icon-[lucide--sun]',\n      show: canUseLighting && !!lightConfig.value && !!modelConfig.value\n    },\n    {\n      key: 'hdri',\n      label: t('load3d.hdri.label'),\n      icon: 'icon-[lucide--globe]',\n      show: canUseHdri && !!lightConfig.value\n    },\n    {\n      key: 'gizmo',\n      label: t('load3d.gizmo.label'),\n      icon: 'icon-[lucide--axis-3d]',\n      show: canUseGizmo && !!modelConfig.value\n    }\n  ].filter((c) => c.show)\n)\n\nconst activeCategory = ref('scene')\nconst activeDef = computed(() =>\n  categoryDefs.value.find((c) => c.key === activeCategory.value)\n)\nconst activeLabel = computed(() => activeDef.value?.label ?? '')\nconst activeIcon = computed(() => activeDef.value?.icon ?? '')\nwatch(categoryDefs, (defs) => {\n  if (!defs.some((c) => c.key === activeCategory.value)) {\n    activeCategory.value = defs[0]?.key ?? 'scene'\n  }\n})\n\nconst exclusivePopover = usePopoverExclusivity()\nconst categoryMenuOpen = exclusivePopover('category-menu')\nconst exportOpen = exclusivePopover('export')\n\nconst sceneHasImage = computed(\n  () =>\n    !!sceneConfig.value?.backgroundImage &&\n    sceneConfig.value.backgroundImage !== ''\n)\nconst hdriActive = computed(\n  () =>\n    !!lightConfig.value?.hdri?.hdriPath && !!lightConfig.value?.hdri?.enabled\n)\nconst isOriginalMaterial = computed(\n  () => modelConfig.value?.materialMode === 'original'\n)\nconst cameraFov = computed({\n  get: () => cameraConfig.value?.fov ?? 0,\n  set: (value) => {\n    if (cameraConfig.value) cameraConfig.value.fov = value\n  }\n})\n\nconst exportFormats = computed(() => getExportFormatOptions(sourceFormat))\n\nconst topBarRef = ref<HTMLElement | null>(null)\nconst { width: topW } = useElementSize(topBarRef)\nconst compactWidthThreshold = 480\nconst compact = computed(\n  () => topW.value > 0 && topW.value < compactWidthThreshold\n)\n\nfunction selectCategory(key: string) {\n  activeCategory.value = key\n  categoryMenuOpen.value = false\n}\n\nfunction onExport(format: string) {\n  emit('exportModel', format)\n  exportOpen.value = false\n}\n</script>\n","<template>\n  <div class=\"flex size-full flex-col\">\n    <div\n      ref=\"topBarRef\"\n      class=\"flex h-10 shrink-0 items-center gap-1 bg-interface-menu-surface px-2\"\n      @wheel.stop\n    >\n      <Popover v-model:open=\"categoryMenuOpen\">\n        <PopoverTrigger as-child>\n          <Button\n            variant=\"textonly\"\n            size=\"unset\"\n            :tooltip=\"compact ? activeLabel : ''\"\n            tooltip-side=\"bottom\"\n            :class=\"chipClass\"\n            type=\"button\"\n            :aria-label=\"compact ? activeLabel : undefined\"\n            data-testid=\"load3d-category-menu\"\n          >\n            <i v-if=\"compact\" :class=\"cn(activeIcon, 'size-4')\" />\n            <template v-else>{{ activeLabel }}</template>\n            <i class=\"icon-[lucide--chevron-down] size-4 opacity-70\" />\n          </Button>\n        </PopoverTrigger>\n        <PopoverContent\n          side=\"bottom\"\n          align=\"start\"\n          :side-offset=\"8\"\n          :class=\"menuPanelClass\"\n        >\n          <button\n            v-for=\"c in categoryDefs\"\n            :key=\"c.key\"\n            type=\"button\"\n            :class=\"\n              cn(\n                menuButtonClass,\n                activeCategory === c.key && selectedMenuButtonClass\n              )\n            \"\n            :aria-pressed=\"activeCategory === c.key\"\n            @click=\"selectCategory(c.key)\"\n          >\n            <i :class=\"cn(c.icon, 'size-4')\" />\n            {{ c.label }}\n          </button>\n        </PopoverContent>\n      </Popover>\n\n      <div class=\"mx-1 h-5 w-px shrink-0 bg-interface-menu-stroke\" />\n\n      <SceneMenuGroup\n        v-if=\"activeCategory === 'scene' && sceneConfig\"\n        v-model:config=\"sceneConfig\"\n        v-model:fov=\"cameraFov\"\n        :compact\n        :can-use-background-image=\"canUseBackgroundImage\"\n        :hdri-active=\"hdriActive\"\n        @update-background-image=\"emit('updateBackgroundImage', $event)\"\n      />\n      <ModelMenuGroup\n        v-else-if=\"activeCategory === 'model' && modelConfig\"\n        v-model:config=\"modelConfig\"\n        :compact\n        :material-modes=\"materialModes\"\n        :has-skeleton=\"hasSkeleton\"\n      />\n      <CameraMenuGroup\n        v-else-if=\"activeCategory === 'camera' && cameraConfig\"\n        v-model:config=\"cameraConfig\"\n        :compact\n      />\n      <LightMenuGroup\n        v-else-if=\"activeCategory === 'light' && lightConfig && modelConfig\"\n        v-model:config=\"lightConfig\"\n        :compact\n        :is-original-material=\"isOriginalMaterial\"\n      />\n      <HdriMenuGroup\n        v-else-if=\"activeCategory === 'hdri' && lightConfig\"\n        v-model:config=\"lightConfig\"\n        :compact\n        :scene-has-image=\"sceneHasImage\"\n        @update-hdri-file=\"emit('updateHdriFile', $event)\"\n      />\n      <GizmoMenuGroup\n        v-else-if=\"activeCategory === 'gizmo' && modelConfig\"\n        v-model:config=\"modelConfig\"\n        :compact\n        @toggle-gizmo=\"emit('toggleGizmo', $event)\"\n        @set-gizmo-mode=\"emit('setGizmoMode', $event)\"\n        @reset-gizmo-transform=\"emit('resetGizmoTransform')\"\n      />\n    </div>\n\n    <div class=\"relative min-h-0 flex-1 overflow-hidden\">\n      <slot />\n      <div\n        v-if=\"isRecording\"\n        class=\"pointer-events-none absolute inset-0 border-2 border-node-component-executing\"\n      />\n    </div>\n\n    <AnimationMenuStrip\n      v-if=\"animations.length > 0\"\n      v-model:playing=\"playing\"\n      v-model:selected-speed=\"selectedSpeed\"\n      v-model:selected-animation=\"selectedAnimation\"\n      v-model:animation-progress=\"animationProgress\"\n      :animations=\"animations\"\n      :animation-duration=\"animationDuration\"\n      :compact\n      @seek=\"emit('seek', $event)\"\n    />\n\n    <div\n      class=\"flex h-10 shrink-0 items-center justify-between gap-1 bg-interface-menu-surface px-2\"\n      @wheel.stop\n    >\n      <div class=\"flex items-center gap-1\">\n        <RecordMenuControl\n          v-if=\"canUseRecording\"\n          v-model:is-recording=\"isRecording\"\n          v-model:has-recording=\"hasRecording\"\n          v-model:recording-duration=\"recordingDuration\"\n          :compact\n          @start-recording=\"emit('startRecording')\"\n          @stop-recording=\"emit('stopRecording')\"\n          @export-recording=\"emit('exportRecording')\"\n          @clear-recording=\"emit('clearRecording')\"\n        />\n      </div>\n      <div class=\"flex items-center gap-1\">\n        <ViewerControls\n          v-if=\"enableViewer && node\"\n          :node=\"node as LGraphNode\"\n        />\n        <Button\n          v-if=\"canFitToViewer\"\n          variant=\"textonly\"\n          size=\"icon\"\n          :tooltip=\"t('load3d.fitToViewer')\"\n          type=\"button\"\n          :aria-label=\"t('load3d.fitToViewer')\"\n          @click=\"emit('fitToViewer')\"\n        >\n          <i class=\"icon-[lucide--scan] size-4\" />\n        </Button>\n        <Button\n          v-if=\"canCenterCameraOnModel\"\n          variant=\"textonly\"\n          size=\"icon\"\n          :tooltip=\"t('load3d.centerCameraOnModel')\"\n          type=\"button\"\n          :aria-label=\"t('load3d.centerCameraOnModel')\"\n          @click=\"emit('centerCamera')\"\n        >\n          <i class=\"icon-[lucide--crosshair] size-4\" />\n        </Button>\n        <Popover v-if=\"canExport\" v-model:open=\"exportOpen\">\n          <PopoverTrigger as-child>\n            <Button\n              variant=\"textonly\"\n              size=\"icon\"\n              :tooltip=\"t('load3d.export')\"\n              type=\"button\"\n              :aria-label=\"t('load3d.export')\"\n            >\n              <i class=\"icon-[lucide--download] size-4\" />\n            </Button>\n          </PopoverTrigger>\n          <PopoverContent\n            side=\"top\"\n            align=\"end\"\n            :side-offset=\"8\"\n            :class=\"menuPanelClass\"\n          >\n            <button\n              v-for=\"format in exportFormats\"\n              :key=\"format.value\"\n              type=\"button\"\n              :class=\"menuButtonClass\"\n              @click=\"onExport(format.value)\"\n            >\n              {{ format.label }}\n            </button>\n          </PopoverContent>\n        </Popover>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useElementSize } from '@vueuse/core'\nimport { PopoverTrigger } from 'reka-ui'\nimport { computed, ref, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport AnimationMenuStrip from '@/components/load3d/menubar/AnimationMenuStrip.vue'\nimport CameraMenuGroup from '@/components/load3d/menubar/CameraMenuGroup.vue'\nimport GizmoMenuGroup from '@/components/load3d/menubar/GizmoMenuGroup.vue'\nimport HdriMenuGroup from '@/components/load3d/menubar/HdriMenuGroup.vue'\nimport LightMenuGroup from '@/components/load3d/menubar/LightMenuGroup.vue'\nimport {\n  chipClass,\n  menuPanelClass\n} from '@/components/load3d/menubar/menuBarStyles'\nimport ModelMenuGroup from '@/components/load3d/menubar/ModelMenuGroup.vue'\nimport RecordMenuControl from '@/components/load3d/menubar/RecordMenuControl.vue'\nimport SceneMenuGroup from '@/components/load3d/menubar/SceneMenuGroup.vue'\nimport { usePopoverExclusivity } from '@/components/load3d/menubar/usePopoverExclusivity'\nimport ViewerControls from '@/components/load3d/controls/ViewerControls.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport Popover from '@/components/ui/popover/Popover.vue'\nimport PopoverContent from '@/components/ui/popover/PopoverContent.vue'\nimport {\n  menuButtonClass,\n  selectedMenuButtonClass\n} from '@/components/ui/menu/menuStyles'\nimport { getExportFormatOptions } from '@/extensions/core/load3d/constants'\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport type {\n  AnimationItem,\n  CameraConfig,\n  GizmoMode,\n  LightConfig,\n  MaterialMode,\n  ModelConfig,\n  SceneConfig\n} from '@/extensions/core/load3d/interfaces'\n\nconst {\n  animations = [],\n  animationDuration = 0,\n  canUseLighting = true,\n  canUseHdri = true,\n  canUseGizmo = true,\n  canExport = true,\n  canUseBackgroundImage = true,\n  canFitToViewer = true,\n  canCenterCameraOnModel = true,\n  canUseRecording = true,\n  enableViewer = false,\n  node = null,\n  materialModes = ['original', 'clay', 'normal', 'wireframe'],\n  hasSkeleton = false,\n  sourceFormat = null\n} = defineProps<{\n  animations?: AnimationItem[]\n  animationDuration?: number\n  canUseLighting?: boolean\n  canUseHdri?: boolean\n  canUseGizmo?: boolean\n  canExport?: boolean\n  canUseBackgroundImage?: boolean\n  canFitToViewer?: boolean\n  canCenterCameraOnModel?: boolean\n  canUseRecording?: boolean\n  enableViewer?: boolean\n  node?: LGraphNode | null\n  materialModes?: readonly MaterialMode[]\n  hasSkeleton?: boolean\n  sourceFormat?: string | null\n}>()\n\nconst sceneConfig = defineModel<SceneConfig>('sceneConfig')\nconst modelConfig = defineModel<ModelConfig>('modelConfig')\nconst cameraConfig = defineModel<CameraConfig>('cameraConfig')\nconst lightConfig = defineModel<LightConfig>('lightConfig')\nconst isRecording = defineModel<boolean>('isRecording')\nconst hasRecording = defineModel<boolean>('hasRecording')\nconst recordingDuration = defineModel<number>('recordingDuration')\nconst playing = defineModel<boolean>('playing')\nconst selectedSpeed = defineModel<number>('selectedSpeed')\nconst selectedAnimation = defineModel<number>('selectedAnimation')\nconst animationProgress = defineModel<number>('animationProgress')\n\nconst emit = defineEmits<{\n  (e: 'seek', progress: number): void\n  (e: 'updateBackgroundImage', file: File | null): void\n  (e: 'updateHdriFile', file: File | null): void\n  (e: 'exportModel', format: string): void\n  (e: 'fitToViewer'): void\n  (e: 'centerCamera'): void\n  (e: 'toggleGizmo', enabled: boolean): void\n  (e: 'setGizmoMode', mode: GizmoMode): void\n  (e: 'resetGizmoTransform'): void\n  (e: 'startRecording'): void\n  (e: 'stopRecording'): void\n  (e: 'exportRecording'): void\n  (e: 'clearRecording'): void\n}>()\n\nconst { t } = useI18n()\n\nconst categoryDefs = computed(() =>\n  [\n    {\n      key: 'scene',\n      label: t('load3d.scene'),\n      icon: 'icon-[lucide--layers]',\n      show: !!sceneConfig.value\n    },\n    {\n      key: 'model',\n      label: t('load3d.model3d'),\n      icon: 'icon-[lucide--box]',\n      show: !!modelConfig.value\n    },\n    {\n      key: 'camera',\n      label: t('load3d.camera'),\n      icon: 'icon-[lucide--camera]',\n      show: !!cameraConfig.value\n    },\n    {\n      key: 'light',\n      label: t('load3d.light'),\n      icon: 'icon-[lucide--sun]',\n      show: canUseLighting && !!lightConfig.value && !!modelConfig.value\n    },\n    {\n      key: 'hdri',\n      label: t('load3d.hdri.label'),\n      icon: 'icon-[lucide--globe]',\n      show: canUseHdri && !!lightConfig.value\n    },\n    {\n      key: 'gizmo',\n      label: t('load3d.gizmo.label'),\n      icon: 'icon-[lucide--axis-3d]',\n      show: canUseGizmo && !!modelConfig.value\n    }\n  ].filter((c) => c.show)\n)\n\nconst activeCategory = ref('scene')\nconst activeDef = computed(() =>\n  categoryDefs.value.find((c) => c.key === activeCategory.value)\n)\nconst activeLabel = computed(() => activeDef.value?.label ?? '')\nconst activeIcon = computed(() => activeDef.value?.icon ?? '')\nwatch(categoryDefs, (defs) => {\n  if (!defs.some((c) => c.key === activeCategory.value)) {\n    activeCategory.value = defs[0]?.key ?? 'scene'\n  }\n})\n\nconst exclusivePopover = usePopoverExclusivity()\nconst categoryMenuOpen = exclusivePopover('category-menu')\nconst exportOpen = exclusivePopover('export')\n\nconst sceneHasImage = computed(\n  () =>\n    !!sceneConfig.value?.backgroundImage &&\n    sceneConfig.value.backgroundImage !== ''\n)\nconst hdriActive = computed(\n  () =>\n    !!lightConfig.value?.hdri?.hdriPath && !!lightConfig.value?.hdri?.enabled\n)\nconst isOriginalMaterial = computed(\n  () => modelConfig.value?.materialMode === 'original'\n)\nconst cameraFov = computed({\n  get: () => cameraConfig.value?.fov ?? 0,\n  set: (value) => {\n    if (cameraConfig.value) cameraConfig.value.fov = value\n  }\n})\n\nconst exportFormats = computed(() => getExportFormatOptions(sourceFormat))\n\nconst topBarRef = ref<HTMLElement | null>(null)\nconst { width: topW } = useElementSize(topBarRef)\nconst compactWidthThreshold = 480\nconst compact = computed(\n  () => topW.value > 0 && topW.value < compactWidthThreshold\n)\n\nfunction selectCategory(key: string) {\n  activeCategory.value = key\n  categoryMenuOpen.value = false\n}\n\nfunction onExport(format: string) {\n  emit('exportModel', format)\n  exportOpen.value = false\n}\n</script>\n","<template>\n  <div\n    ref=\"container\"\n    class=\"relative size-full min-h-[200px]\"\n    data-capture-wheel=\"true\"\n    tabindex=\"-1\"\n    @pointerdown.stop=\"focusContainer\"\n    @mousedown.stop\n    @contextmenu.stop.prevent\n    @dragover.prevent.stop=\"handleDragOver\"\n    @dragleave.stop=\"handleDragLeave\"\n    @drop.prevent.stop=\"handleDrop\"\n  >\n    <LoadingOverlay :loading=\"loading\" :loading-message=\"loadingMessage\" />\n    <div\n      v-if=\"!isPreview && isDragging\"\n      class=\"pointer-events-none absolute inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm\"\n    >\n      <div\n        class=\"rounded-lg border-2 border-dashed border-blue-400 bg-blue-500/20 px-6 py-4 text-lg font-medium text-blue-100\"\n      >\n        {{ dragMessage }}\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, onMounted, onUnmounted, ref } from 'vue'\n\nimport LoadingOverlay from '@/components/common/LoadingOverlay.vue'\nimport { useLoad3dDrag } from '@/composables/useLoad3dDrag'\n\nconst props = defineProps<{\n  initializeLoad3d: (containerRef: HTMLElement) => Promise<void>\n  cleanup: () => void\n  loading: boolean\n  loadingMessage: string\n  onModelDrop?: (file: File) => void | Promise<void>\n  isPreview: boolean\n}>()\n\nconst container = ref<HTMLElement | null>(null)\n\nfunction focusContainer() {\n  container.value?.focus()\n}\n\nconst { isDragging, dragMessage, handleDragOver, handleDragLeave, handleDrop } =\n  useLoad3dDrag({\n    onModelDrop: async (file) => {\n      if (props.onModelDrop) {\n        await props.onModelDrop(file)\n      }\n    },\n    disabled: computed(() => props.isPreview)\n  })\n\nonMounted(() => {\n  if (container.value) {\n    void props.initializeLoad3d(container.value)\n  }\n})\n\nonUnmounted(() => {\n  props.cleanup()\n})\n</script>\n","<template>\n  <div\n    ref=\"container\"\n    class=\"relative size-full min-h-[200px]\"\n    data-capture-wheel=\"true\"\n    tabindex=\"-1\"\n    @pointerdown.stop=\"focusContainer\"\n    @mousedown.stop\n    @contextmenu.stop.prevent\n    @dragover.prevent.stop=\"handleDragOver\"\n    @dragleave.stop=\"handleDragLeave\"\n    @drop.prevent.stop=\"handleDrop\"\n  >\n    <LoadingOverlay :loading=\"loading\" :loading-message=\"loadingMessage\" />\n    <div\n      v-if=\"!isPreview && isDragging\"\n      class=\"pointer-events-none absolute inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm\"\n    >\n      <div\n        class=\"rounded-lg border-2 border-dashed border-blue-400 bg-blue-500/20 px-6 py-4 text-lg font-medium text-blue-100\"\n      >\n        {{ dragMessage }}\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, onMounted, onUnmounted, ref } from 'vue'\n\nimport LoadingOverlay from '@/components/common/LoadingOverlay.vue'\nimport { useLoad3dDrag } from '@/composables/useLoad3dDrag'\n\nconst props = defineProps<{\n  initializeLoad3d: (containerRef: HTMLElement) => Promise<void>\n  cleanup: () => void\n  loading: boolean\n  loadingMessage: string\n  onModelDrop?: (file: File) => void | Promise<void>\n  isPreview: boolean\n}>()\n\nconst container = ref<HTMLElement | null>(null)\n\nfunction focusContainer() {\n  container.value?.focus()\n}\n\nconst { isDragging, dragMessage, handleDragOver, handleDragLeave, handleDrop } =\n  useLoad3dDrag({\n    onModelDrop: async (file) => {\n      if (props.onModelDrop) {\n        await props.onModelDrop(file)\n      }\n    },\n    disabled: computed(() => props.isPreview)\n  })\n\nonMounted(() => {\n  if (container.value) {\n    void props.initializeLoad3d(container.value)\n  }\n})\n\nonUnmounted(() => {\n  props.cleanup()\n})\n</script>\n","<template>\n  <div\n    class=\"relative size-full\"\n    @mouseenter=\"handleMouseEnter\"\n    @mouseleave=\"handleMouseLeave\"\n    @pointerdown.stop\n  >\n    <Load3DMenuBar\n      v-model:scene-config=\"sceneConfig\"\n      v-model:model-config=\"modelConfig\"\n      v-model:camera-config=\"cameraConfig\"\n      v-model:light-config=\"lightConfig\"\n      v-model:is-recording=\"isRecording\"\n      v-model:has-recording=\"hasRecording\"\n      v-model:recording-duration=\"recordingDuration\"\n      v-model:playing=\"playing\"\n      v-model:selected-speed=\"selectedSpeed\"\n      v-model:selected-animation=\"selectedAnimation\"\n      v-model:animation-progress=\"animationProgress\"\n      :animations=\"animations\"\n      :animation-duration=\"animationDuration\"\n      :can-use-gizmo=\"canUseGizmo\"\n      :can-use-lighting=\"canUseLighting\"\n      :can-export=\"canExport\"\n      :can-use-hdri=\"canUseHdri\"\n      :can-use-background-image=\"canUseBackgroundImage\"\n      :can-fit-to-viewer=\"canFitToViewer\"\n      :can-center-camera-on-model=\"canCenterCameraOnModel\"\n      :node=\"node as LGraphNode\"\n      :enable-viewer=\"enable3DViewer\"\n      :can-use-recording=\"canUseRecording && !isPreview\"\n      :material-modes=\"materialModes\"\n      :has-skeleton=\"hasSkeleton\"\n      :source-format=\"sourceFormat\"\n      @update-background-image=\"handleBackgroundImageUpdate\"\n      @update-hdri-file=\"handleHDRIFileUpdate\"\n      @export-model=\"handleExportModel\"\n      @fit-to-viewer=\"handleFitToViewer\"\n      @center-camera=\"handleCenterCameraOnModel\"\n      @toggle-gizmo=\"handleToggleGizmo\"\n      @set-gizmo-mode=\"handleSetGizmoMode\"\n      @reset-gizmo-transform=\"handleResetGizmoTransform\"\n      @start-recording=\"handleStartRecording\"\n      @stop-recording=\"handleStopRecording\"\n      @export-recording=\"handleExportRecording\"\n      @clear-recording=\"handleClearRecording\"\n      @seek=\"handleSeek\"\n    >\n      <Load3DScene\n        v-if=\"node\"\n        :initialize-load3d=\"initializeLoad3d\"\n        :cleanup=\"cleanup\"\n        :loading=\"loading\"\n        :loading-message=\"loadingMessage\"\n        :on-model-drop=\"isPreview ? undefined : handleModelDrop\"\n        :is-preview=\"isPreview\"\n      />\n    </Load3DMenuBar>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, onMounted, ref } from 'vue'\nimport type { Ref } from 'vue'\n\nimport Load3DMenuBar from '@/components/load3d/Load3DMenuBar.vue'\nimport Load3DScene from '@/components/load3d/Load3DScene.vue'\nimport { useLoad3d } from '@/composables/useLoad3d'\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport type { ComponentWidget } from '@/scripts/domWidget'\nimport type { NodeId } from '@/types/nodeId'\nimport type { SimplifiedWidget } from '@/types/simplifiedWidget'\nimport { resolveNode } from '@/utils/litegraphUtil'\n\nconst {\n  widget,\n  nodeId,\n  canUseRecording = true,\n  canUseHdri = true,\n  canUseBackgroundImage = true\n} = defineProps<{\n  widget: ComponentWidget<string[]> | SimplifiedWidget\n  nodeId?: NodeId\n  canUseRecording?: boolean\n  canUseHdri?: boolean\n  canUseBackgroundImage?: boolean\n}>()\n\nfunction isComponentWidget(\n  widget: ComponentWidget<string[]> | SimplifiedWidget\n): widget is ComponentWidget<string[]> {\n  return 'node' in widget && widget.node !== undefined\n}\n\nconst node = ref<LGraphNode | null>(null)\n\nif (isComponentWidget(widget)) {\n  node.value = widget.node\n} else if (nodeId) {\n  onMounted(() => {\n    node.value = resolveNode(nodeId) ?? null\n  })\n}\n\nconst {\n  // configs\n  sceneConfig,\n  modelConfig,\n  cameraConfig,\n  lightConfig,\n\n  // other state\n  isRecording,\n  isPreview,\n  canFitToViewer,\n  canCenterCameraOnModel,\n  canUseGizmo,\n  canUseLighting,\n  canExport,\n  materialModes,\n  hasSkeleton,\n  sourceFormat,\n  hasRecording,\n  recordingDuration,\n  animations,\n  playing,\n  selectedSpeed,\n  selectedAnimation,\n  animationProgress,\n  animationDuration,\n  loading,\n  loadingMessage,\n\n  // Methods\n  initializeLoad3d,\n  handleMouseEnter,\n  handleMouseLeave,\n  handleStartRecording,\n  handleStopRecording,\n  handleExportRecording,\n  handleCl